def solve_type(A, b):
    import numpy as np
    A = np.array(A, dtype=float)
    b = np.array(b, dtype=float).reshape(-1,1)
    aug = np.hstack([A, b])
    rA = np.linalg.matrix_rank(A)
    rAug = np.linalg.matrix_rank(aug)
    if rA == rAug == A.shape[1]:
        return 'Unique solution'
    elif rA == rAug < A.shape[1]:
        return 'Infinite solutions'
    else:
        return 'No solution'

def det4(M):
    # Use Laplace expansion on first row
    def minor(mat, i, j):
        return [row[:j] + row[j+1:] for r, row in enumerate(mat) if r != i]
    def det(mat):
        n = len(mat)
        if n == 1:
            return mat[0][0]
        if n == 2:
            return mat[0][0]*mat[1][1] - mat[0][1]*mat[1][0]
        total = 0
        for col in range(n):
            sign = (-1) ** col
            total += sign * mat[0][col] * det(minor(mat, 0, col))
        return total
    return det(M)

