# Example: check if a set of 2‑D vectors forms a subspace
import numpy as np

def is_subspace(vectors):
    # vectors: list of numpy arrays representing the set
    # 1. zero vector check
    zero = np.zeros_like(vectors[0])
    if not any(np.allclose(v, zero) for v in vectors):
        return False
    # 2. closure under addition
    for i in range(len(vectors)):
        for j in range(len(vectors)):
            s = vectors[i] + vectors[j]
            if not any(np.allclose(s, v) for v in vectors):
                return False
    # 3. closure under scalar multiplication (test a few scalars)
    for v in vectors:
        for c in [-2, 0, 3.5]:
            sv = c * v
            if not any(np.allclose(sv, u) for u in vectors):
                return False
    return True

# Define a candidate set: all multiples of (1,2)
S = [np.array([0,0]), np.array([1,2]), np.array([-3,-6])]
print(is_subspace(S))  # True

